								; divide_d_by_x+1418↓p ...
				push	d			; Save D (A:B) on stack
				push	x			; Save X on stack
				mov	s, x			; X = SP: X now addresses [D_hi, D_lo, X_hi, X_lo]
				mul	a, x + 00h		; partial: A_hi * X_lo -> D
				mov	d, y			; Y = partial product low word
				ld	a, x + 00h		; A = X_lo
				mul	a, x + 03h		; partial: X_lo * D_lo -> D
				add	y, a			; accumulate into Y
				st	b, x + 00h		; save partial low byte
				ld	a, x + 01h		; A = D_hi (from stack)
				mul	a, x + 03h		; partial: D_hi * D_lo
				st	b, x + 03h		; save partial
				xch	a, x + 02h		; swap with X_hi
				mul	a, x + 01h		; partial: X_hi * D_hi
				add	b, x + 00h		; accumulate
				addc	a, #00h			; propagate carry
				add	y, a			; add into Y
				clr	a
				add	b, x + 02h		; add remaining partial
				rolc	a			; carry into A
				add	y, a			; final accumulation
				st	b, x + 02h
				st	y, x + 00h		; store MSW of 32-bit product
				ld	a, x + 00h		; A = MSW high byte
