;   JUMP (proportional, large, on a rich/lean transition) - loc_DABF:
;     var_lambda_avg >= 0xB3  -> rich  -> unk_1C4 += 0x07AE (saturating)
;     var_lambda_avg <= 0x4D  -> lean  -> unk_1C4 -= 0x07AE (to 0)
