				cmp	#05h, var_speed_kph		; Speed > 5 kph?
				bcs	locret_EF47			; No: skip
				cmp	#0C4h, var_ect			; ECT > 0xC4 (warm engine)?
				bcs	locret_EF47			; No: skip
				setb	bit6, var_flags_4E		; All conditions met: enable overrun fuel cut

