; FUNCTION CHUNK AT F770 SIZE 0000002A BYTES

				push	x
				push	y
				clrb	bit0, IRQL			; Clear CPR0 interrupt latch
				tbbc	bit0, LDOUT, ignition_on	; LDOUT.0=0: coil just turned on

; Coil just turned OFF (spark fired): LDOUT.0=1
