; ---------------------------------------------------------------------------
; adc_handler_pim: MAP / turbo boost pressure sensor (PIM)
;
; Input: X = raw 16-bit ADC result from MAP sensor
;
; Scaling:
;   mPIM = max(0, raw_adc - 10560)   (remove the sensor's ZERO-PRESSURE
;                                     output offset, 0x2940 = 0.806V)
;   var_pim2 = mPIM * 1.285156       (scale by 329/256)
;
;   var_pim2 is ABSOLUTE pressure with zero at HARD VACUUM. It is NOT zero
;   at atmospheric - an earlier version of this header and of
;   docs/adc_system.md both said it was, which wrongly implies the ECU
;   cannot represent vacuum. Reference points:
;     0x0000 = -14.9 psi gauge (~0 kPa absolute)
;     0x2E4D =  -8 psi  (typical hot idle)
;     0x6443 =   0 psi  (atmospheric)
;     0x6666 =  +0.3 psi (the out-of-range default below - i.e. limp to
;                         roughly atmospheric, which is why 0x6666)
;     0xDA00 = +17.5 psi (table_boost_limit's cut point, ROM-annotated
;                         "17.6 psi" - an independent check on all of this)
;   Derivation from the sensor transfer function is in docs/adc_system.md.
;
; On out-of-range:
;   Uses default value 0x6666 for up to 15 consecutive errors.
;   After 15 errors: sets error flags (var_error_flags1.5, var_diag_errors_5.3)
;
; Also computes:
;   var_pim_trim_scale = var_pim2 / 2 / 97 = pressure lookup table index for boost limit
;   var_nv_trim_unk_98: PIM calibration trim value stored in PRAM
;
; Outputs: var_pim2 (local), dmatx_pim2 (to CPU2), calls check_boost_limit
; ---------------------------------------------------------------------------

adc_handler_pim:						; DATA XREF: ROM:table_adc_handler↑o

; FUNCTION CHUNK AT FB1A SIZE 00000003 BYTES

				ld	y, #pim_adc_limits	; Check and clamp raw ADC within valid PIM sensor range
				jsr	y + (clamp_rB -	pim_adc_limits)	; Check	and clamp

				ld	a, var_flags_18C	; Get flags
				bcc	adc_handler_pim_ok	; Jump if PIM value not	out of range

				ld	x, #6666h		; Default PIM value
				tbbc	bit2, var_flags_40, loc_FB9E

				setb	bit5, var_error_flags1	; Set PIM sensor error flag
				setb	bit3, var_diag_errors_5	; Set sensor error flag

loc_FB9E:							; CODE XREF: adc_handler_pim+D↑j
				cmpb	a, #01h			; Check	if bit 0 set
				bne	loc_FBA8		; Jump if it is	already	(PIM sensor out	of range detected)

				or	a, #01h			; Set PIM out of range flag
				clr	var_cnt_sensor_error	; Reset	counter
				bra	loc_FBBF

; ───────────────────────────────────────────────────────────────────────────

loc_FBA8:							; CODE XREF: adc_handler_pim+16↑j
				cmp	#0Fh, var_cnt_sensor_error ; Check if less than	15 reads out of	range
				bcs	loc_FBAF		; Jump if so

				setb	bit5, var_error_flags1	; Set PIM sensor error flag

loc_FBAF:							; CODE XREF: adc_handler_pim+21↑j
				ld	x, #6666h		; Default PIM value
				setb	bit3, var_flags_4D	; Set PIM default value	flag
				bra	loc_FBBF

; ───────────────────────────────────────────────────────────────────────────

adc_handler_pim_ok:						; CODE XREF: adc_handler_pim+8↑j
				and	a, #0FEh		; Clear	bit 0 of flags
				tbbs	bit2, var_flags_40, loc_FBBD

				clrb	bit5, var_error_flags1	; Clear	PIM sensor error flag

loc_FBBD:							; CODE XREF: adc_handler_pim+2E↑j
				clrb	bit3, var_flags_4D	; Clear	PIM default value flag

loc_FBBF:							; CODE XREF: adc_handler_pim+1C↑j
								; adc_handler_pim+2A↑j
				st	a, var_flags_18C	; Store	flags
				mov	x, d			; Copy PIM value in rX to rD
; Remove the MAP sensor's zero-pressure output offset (10560 counts = 0.806V),
; so var_pim2 becomes an ABSOLUTE pressure with zero at hard vacuum - NOT at
; atmospheric. Atmospheric lands near 0x6443; the boost-cut threshold 0xDA00
; is +17.5 psi gauge. (An older comment here read "PIM - 7.86psi", and
; adc_system.md claimed this was a "1-bar atmospheric baseline" - both wrong;
; see that doc for the derivation from the XDF's sensor transfer function.)
				sub	d, #10560		; mPIM = PIM - zero-pressure offset (0.806V)
				bcc	loc_FBCC		; Jump if no underflow

; Underflow means the sensor read BELOW its own zero-pressure voltage - the
; valid input range starts at 0.51V, under the 0.806V zero point, so this is
; electrically reachable but not physically meaningful. A fault guard, not a
; limit that normal vacuum ever reaches.
				clr	a			; Underflow, so	clamp at 0
				clr	b
				bra	loc_FBE0

; ───────────────────────────────────────────────────────────────────────────

loc_FBCC:							; CODE XREF: adc_handler_pim+3C↑j
				mov	d, x			; Copy modified	PIM (mPIM) to rX
				push	b			; Save LSB of mPIM
				mul	a, #073			; rD = (mPIM / 256) * 73
				st	d, word_125		; Store	rD in temporary	store.
				pull	a			; Get LSB of mPIM in rA
				mul	a, #073			; rD = (mPIM % 256) * 73
				add	x, a			; rX = rX + ((mPIM % 256) * 73)	/ 256)
				mov	x, d			; rD = rX
				add	d, word_125		; rD = rX + ((mPIM / 256 * 73))	+
								;	    ((mPIM % 256) * 73)	/ 256);
								; rD = mPim + (mPim * 73 / 256);
								; rD = mPim * 1.285156
				bcc	loc_FBE0		; Jump if no overflow

				ld	d, #0FFFFh		; Overflow, set	to max value

loc_FBE0:							; CODE XREF: adc_handler_pim+40↑j
								; adc_handler_pim+51↑j
				tbbs	bit0, var_flags_40, loc_FC30

				tbbs	bit1, var_flags_47, loc_FBF6

				cmp	#0Ch, TIMER		; Timer	MSB (bit11~bit18)
				bcs	loc_FC30

				setb	bit1, var_flags_47
				st	a, var_pim_baseline
				tbbc	bit0, var_io_input1, loc_FC30 ;	Jump if	STA low	(starter not running)


loc_FBF2:							; CODE XREF: adc_handler_pim+81↓j
				setb	bit2, var_flags_47
				bra	loc_FC30

; ───────────────────────────────────────────────────────────────────────────

loc_FBF6:							; CODE XREF: adc_handler_pim+59↑j
				sub	d, var_pim2
				rorc	a
				rorc	b
				jsr	divide_rD_2_signed

				add	d, var_pim2
				mov	d, y
				tbbs	bit2, var_flags_47, loc_FC19

				sub	a, var_pim_baseline
				bcc	loc_FC08

				neg	a

loc_FC08:							; CODE XREF: adc_handler_pim+7B↑j
				cmp	a, #01h
				mov	y, d
				bgt	loc_FBF2

				tbbc	bit0, var_io_input1, loc_FC19 ;	Jump if	STA low	(starter not running)

				setb	bit2, var_flags_47
				cmp	#0FFh, var_cnt_C7
				bcs	loc_FC19

				setb	bit0, var_flags_47

loc_FC19:							; CODE XREF: adc_handler_pim+76↑j
								; adc_handler_pim+83↑j ...
				tbbc	bit0, var_flags_47, loc_FC30

				tbbc	bit5, RAMST, loc_FC30	; Built-in RAM status

				push	d
				ld	b, var_pim_baseline
				ld	y, #nv_98_limits
				jsr	y + (clamp_rB -	nv_98_limits) ; C3D7

				ld	x, #var_nv_trim_unk_98
				jsr	write_rB_nv_ram

				clrb	bit0, var_flags_47
				pull	d

loc_FC30:							; CODE XREF: adc_handler_pim:loc_FBE0↑j
								; adc_handler_pim+5F↑j ...
				st	d, var_pim2
				st	d, dmatx_pim2
				jmp	loc_FC57

