				bcc	loc_FC66		; No overflow: store scaled value


loc_FC64:							; CODE XREF: adc_handler_o2_heater+2↑j
				ld	a, #0FFh		; Overflowed, so set to	max value

loc_FC66:							; CODE XREF: adc_handler_o2_heater+5↑j
