; ---------------------------------------------------------------------------
; adc_handler_tha: intake air temperature sensor (THA)
;
; Input: B = raw 8-bit ADC value from THA NTC thermistor
;
; Encoding: NTC thermistor produces high voltage (high ADC) when cold,
; low voltage when hot. The raw value is XOR 0xFF to invert so:
;   var_tha high value = hot, low value = cold (matches intuition)
;
; On out-of-range (clamped by tha_adc_limits):
;   Default: B = 0x79, XOR 0xFF = 0x86 (approximately 20 degC)
;   After 15 consecutive errors: set var_error_flags1.4, var_diag_errors_5.3
;   First error: set var_flags_18C.2, reset error counter
;
; Outputs: var_tha = B XOR 0xFF, dmatx_tha to CPU2
; ---------------------------------------------------------------------------

adc_handler_tha:						; DATA XREF: ROM:table_adc_handler↑o
				ld	y, #tha_adc_limits	; Check and clamp raw ADC within THA sensor range
				jsr	y + (clamp_rB -	tha_adc_limits)

				ld	a, var_flags_18C	; A = current sensor status flags
				bcc	loc_FF0D		; C clear: value in range

				cmpb	a, #04h			; Already flagged as out-of-range (bit2 set)?
				bne	loc_FEFC		; Yes: skip first-error setup

				or	a, #04h			; Set THA out-of-range flag (var_flags_18C.2)
				clr	var_cnt_sensor_error	; Reset error counter on first detection

loc_FEFC:							; CODE XREF: ROM:FEF6↑j
				tbbs	bit2, var_flags_40, loc_FF05

				cmp	#0Fh, var_cnt_sensor_error ; Check if less than	15 reads out of	range
				bcs	loc_FF09		; Jump if so

; ───────────────────────────────────────────────────────────────────────────
				.db  8Ch ; î			; Skip next instruction
; ───────────────────────────────────────────────────────────────────────────

loc_FF05:							; CODE XREF: ROM:loc_FEFC↑j
				setb	bit3, var_diag_errors_5	; Set sensor error flag
				setb	bit4, var_error_flags1	; Set THA sensor error flag

loc_FF09:							; CODE XREF: ROM:FF02↑j
				ld	b, #79h			; 79h ^	0FFh = 86h - Default to	20 deg
				bra	loc_FF14

; ───────────────────────────────────────────────────────────────────────────

loc_FF0D:							; CODE XREF: ROM:FEF2↑j
				tbbs	bit2, var_flags_40, loc_FF12

				clrb	bit4, var_error_flags1	; Clear	THA sensor error flag

loc_FF12:							; CODE XREF: ROM:loc_FF0D↑j
